117:     if (state.lastTapAt !== null) {
118:       const interval = now - state.lastTapAt;
119:       if (interval > LONG_PAUSE) {
120:         state.intervals = [];
121:         state.pendingIntervals = [];
122:       } else if (interval >= MIN_TAP_INTERVAL && interval <= MAX_TAP_INTERVAL) {
123:         acceptTapInterval(interval);
124:       } else {
125:         state.pendingIntervals = [];
126:       }
127:     }
128:     state.lastTapAt = now;
129: 
130:     if (!state.bpm) {
