138:   function acceptTapInterval(interval) {
139:     const baseline = median(state.intervals);
140:     if (!baseline || Math.abs(interval - baseline) <= baseline * OUTLIER_TOLERANCE) {
141:       state.intervals.push(interval);
142:       state.intervals = state.intervals.slice(-6);
143:       state.pendingIntervals = [];
144:     } else {
145:       const pendingBaseline = median(state.pendingIntervals);
146:       if (!pendingBaseline || Math.abs(interval - pendingBaseline) > pendingBaseline * OUTLIER_TOLERANCE) {
147:         state.pendingIntervals = [interval];
148:       } else {
149:         state.pendingIntervals.push(interval);
150:         if (state.pendingIntervals.length >= 2) {
151:           state.intervals = state.pendingIntervals.slice(-6);
152:           state.pendingIntervals = [];
153:         }
154:       }
155:     }
156: 
157:     if (!state.intervals.length) return;
158:     const previousBpm = state.bpm;
159:     const estimate = estimateBpm(state.intervals);
160:     state.bpm = estimate;
161:     ui.bpm.textContent = String(estimate);
162:     ui.tempoCaption.textContent = `Pulso estimado · ${effectiveTempo()} BPM de práctica`;
163:     setTempoReady(true);
164:     if (state.running && previousBpm !== estimate) adjustClockTempo();
165:     else startClock();
166:   }
