168:   function median(values) {
169:     if (!values.length) return null;
170:     const ordered = [...values].sort((a, b) => a - b);
171:     const middle = Math.floor(ordered.length / 2);
172:     return ordered.length % 2 ? ordered[middle] : (ordered[middle - 1] + ordered[middle]) / 2;
173:   }
