245:   const CLOCK_LOOKAHEAD_MS = 100;
246:   const CLOCK_LOOP_MS = 25;
247:   const MAX_CLOCK_LATENESS_MS = 50;
248: 
249:   function scheduleLoop(generation) {
250:     if (!state.running || generation !== state.generation) return;
251:     const now = performance.now();
252:     if (state.nextTickAt < now - MAX_CLOCK_LATENESS_MS) {
253:       clearClockTimers();
254:       state.tickNumber = Math.max(0, state.lastTickNumber + 1);
255:       state.nextTickAt = now + 8;
256:     }
257:     while (state.nextTickAt <= now + CLOCK_LOOKAHEAD_MS) {
258:       const scheduledAt = state.nextTickAt;
259:       const tick = state.tickNumber++;
260:       const grid = clockGrid(tick);
261:       queueTick(scheduledAt, tick, grid, generation);
262:       if (state.soundOn) scheduleClick(scheduledAt, grid.isAccent);
263:       state.nextTickAt += grid.stepMs;
264:     }
265:     state.timer = window.setTimeout(() => scheduleLoop(generation), CLOCK_LOOP_MS);
266:   }
