445:   function resumeAudio() {
446:     const AudioContextClass = window.AudioContext || window.webkitAudioContext;
447:     if (!AudioContextClass) return;
448:     try {
449:       if (!state.audio) state.audio = new AudioContextClass();
450:       if (state.audio.state === 'suspended') state.audio.resume();
451:     } catch (_) {
452:       // Visual timing remains available if Web Audio is unavailable.
453:     }
454:   }
